import{_ as t,o,c as a,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Usage in VS Code","description":"","frontmatter":{},"headers":[],"relativePath":"usage/vscode.md","filePath":"usage/vscode.md"}'),d={name:"usage/vscode.md"};function n(i,e,c,s,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="usage-in-vs-code" tabindex="-1">Usage in VS Code <a class="header-anchor" href="#usage-in-vs-code" aria-label="Permalink to &quot;Usage in VS Code&quot;">​</a></h1><p>Open a Verilog or SystemVerilog file. LazyVerilog starts on its own. Not installed yet? See <a href="./../installation/vscode">Install for VS Code</a>.</p><p>Hover, go to definition, find references, rename, completion, and signature help use VS Code&#39;s standard shortcuts. Code actions (<code>Ctrl+.</code>) offer <a href="./../autoinst/">AutoInst</a>, <a href="./../autowire/">AutoWire</a>, <a href="./../autoarg/">AutoArg</a>, <a href="./../autofunc/">AutoFunc</a>, and <a href="./../autoff/">AutoFF</a> when the cursor is on a supported construct, and <a href="./../linter/options#quick-fixes">quick fixes</a> for some lint diagnostics. Outside a class, the menu also offers <code>Insert always_ff block</code> and <code>Insert always_comb block</code>, which insert an empty template at the cursor line.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p>Open the Command Palette with <code>Ctrl+Shift+P</code>:</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>LazyVerilog: Format Document</code></td><td>Format the file</td></tr><tr><td><code>LazyVerilog: Lint Current File</code></td><td>Show diagnostics for the file</td></tr><tr><td><code>LazyVerilog: Lint All Files</code></td><td>Show diagnostics for all indexed project files</td></tr><tr><td><code>LazyVerilog: Show RTL Hierarchy</code></td><td>Open the <a href="./../rtl-tree/">module hierarchy</a></td></tr><tr><td><code>LazyVerilog: Show RTL Hierarchy (Reverse)</code></td><td>Open the reverse hierarchy from the current module</td></tr><tr><td><code>LazyVerilog: Refresh RTL Tree</code></td><td>Rebuild the tree shown in the RTL Hierarchy view</td></tr><tr><td><code>LazyVerilog: Interface</code></td><td>Inspect and edit instance connections (<a href="./../interface">Interface</a>)</td></tr><tr><td><code>LazyVerilog: Connect</code></td><td>Connect two modules through the hierarchy (<a href="./../connect">Connect</a>)</td></tr></tbody></table><h2 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h2><p><code>Format Document</code> (<code>Shift+Alt+F</code>) and <code>LazyVerilog: Format Document</code> always format. Saving formats only when <code>[format].enable_format_on_save = true</code> is set in <code>lazyverilog.toml</code>: the server formats in <code>textDocument/willSaveWaitUntil</code>, which VS Code sends on every save, so <code>editor.formatOnSave</code> is not needed. If you also turn on <code>editor.formatOnSave</code> for these files, a save formats twice (the second pass changes nothing).</p>',8)])])}const u=t(d,[["render",n]]);export{m as __pageData,u as default};
